import sys, types, threading

def _load_mod(name: str, src: str):
    mod = types.ModuleType(name)
    mod.__file__ = f"<bundled:{name}.py>"
    sys.modules[name] = mod
    exec(compile(src, f"{name}.py", "exec"), mod.__dict__)
    return mod

